type WorldStateHandle = Readonly<{
  Fen: string;
  Zef: string;
}>;

export const protocol: WorldProtocol<WorldStateHandle> = {
  reset(): WorldStateHandle {
    return { Fen: "pex", Zef: "pex" };
  },

  applyOperation(state, operationDisplayName) {
    if (operationDisplayName !== "lockFenZef") {
      return {
        success: false,
        error: `Unknown operation: ${operationDisplayName}`,
      };
    }

    if (state.Fen !== "pex" || state.Zef !== "pex") {
      return {
        success: false,
        error: "lockFenZef requires Fen and Zef to both be in pex",
      };
    }

    return {
      success: true,
      newState: { Fen: "dor", Zef: "dor" },
    };
  },

  getEntityState(state, entityDisplayName) {
    if (entityDisplayName === "Fen") return state.Fen;
    if (entityDisplayName === "Zef") return state.Zef;
    return "unknown";
  },

  toAbstractSnapshot(state) {
    return {
      Fen: state.Fen,
      Zef: state.Zef,
    };
  },
};
